<?php
require_once dirname(__DIR__).'/app/bootstrap.php';
if(array_key_exists('lat',$_GET)||array_key_exists('lng',$_GET)){require_login(current_request_target());header('Cache-Control: private, no-store, max-age=0');header('X-Robots-Tag: noindex, nofollow, noarchive');}
$activeNav='discover';
$q=trim((string)($_GET['q']??''));$lat=filter_var($_GET['lat']??null,FILTER_VALIDATE_FLOAT);$lng=filter_var($_GET['lng']??null,FILTER_VALIDATE_FLOAT);$radius=max(1,min(100,(int)($_GET['radius']??25)));
$category='';$queryText=text_lower($q);
$intentMap=[
 'Food & Cafes'=>['coffee','cafe','restaurant','food','breakfast','brunch','bakery','tea','eat','dining'],
 'Health & Wellness'=>['doctor','dentist','clinic','hospital','gym','fitness','yoga','wellness','pharmacy'],
 'Home Services'=>['plumber','electrician','repair','cleaning','painter','carpenter','maintenance'],
 'Stay & Travel'=>['hotel','stay','guest house','homestay','travel','accommodation'],
 'Heritage & Spots'=>['museum','heritage','park','garden','landmark','tourist','culture'],
 'Shopping'=>['shop','shopping','market','store','boutique'],
 'Tech Hubs'=>['coworking','workspace','wifi','office','computer','tech'],
 'Professional Services'=>['lawyer','accountant','consultant','agency','professional']
];
foreach($intentMap as $cat=>$words){foreach($words as $word){if(preg_match('/\\b'.preg_quote($word,'/').'\\b/u',$queryText)){$category=$cat;break 2;}}}
$cleanQ=$queryText;
foreach(['near me','nearby','around me','find','show me','best','please','in my area','open now','under ₹','under rs','below ₹','below rs','budget ₹'] as $f){$cleanQ=str_ireplace($f,' ',$cleanQ);}
if($category!==''){
    $categoryWords=$intentMap[$category]??[];
    usort($categoryWords,fn($a,$b)=>strlen($b)<=>strlen($a));
    foreach($categoryWords as $word){$cleanQ=preg_replace('/\b'.preg_quote($word,'/').'\b/u',' ',$cleanQ)??$cleanQ;}
}
$cleanQ=trim(preg_replace('/[^\pL\pN]+/u',' ',$cleanQ)??$cleanQ);
$tokens=array_values(array_filter(preg_split('/\s+/u',$cleanQ)?:[],fn($t)=>text_len($t)>1&&!in_array(text_lower($t),['in','at','near','with','for','and','or','a','an','the','of','to','under','below','from','shop','place','places','business','businesses','local','around'],true)));
$where=["status='published'"];$params=[];
if($category!==''){$where[]='category=:cat';$params[':cat']=$category;}
foreach($tokens as $i=>$token){$key=':term'.$i;$where[]='(name LIKE '.$key.' OR description LIKE '.$key.' OR tags LIKE '.$key.' OR location LIKE '.$key.' OR city LIKE '.$key.')';$params[$key]='%'.$token.'%';}
$sql='SELECT * FROM listings WHERE '.implode(' AND ',$where).' ORDER BY sponsored DESC,featured DESC,name LIMIT 100';$st=db()->prepare($sql);$st->execute($params);$results=$st->fetchAll();record_search($q,'',count($results));
$nearby=false;
if($lat!==false&&$lng!==false&&$lat!==null&&$lng!==null&&abs($lat)<=90&&abs($lng)<=180){$nearby=true;$results=array_values(array_filter($results,function($r)use($lat,$lng,$radius){if($r['latitude']===null||$r['longitude']===null)return false;$dlat=deg2rad((float)$r['latitude']-(float)$lat);$dlng=deg2rad((float)$r['longitude']-(float)$lng);$a=sin($dlat/2)**2+cos(deg2rad((float)$lat))*cos(deg2rad((float)$r['latitude']))*sin($dlng/2)**2;$d=6371*2*atan2(sqrt($a),sqrt(max(0,1-$a)));$r['_distance']=$d;return $d<=$radius;}));foreach($results as &$r){$dlat=deg2rad((float)$r['latitude']-(float)$lat);$dlng=deg2rad((float)$r['longitude']-(float)$lng);$a=sin($dlat/2)**2+cos(deg2rad((float)$lat))*cos(deg2rad((float)$r['latitude']))*sin($dlng/2)**2;$r['_distance']=6371*2*atan2(sqrt($a),sqrt(max(0,1-$a)));}unset($r);usort($results,fn($a,$b)=>$a['_distance']<=>$b['_distance']);}
$personalized=[];$member=current_user();if($member){$ps=db()->prepare("SELECT l.category,COUNT(*) n FROM favorites f JOIN listings l ON l.id=f.listing_id WHERE f.user_id=:u GROUP BY l.category ORDER BY n DESC LIMIT 3");$ps->execute([':u'=>current_user_id()]);$cats=array_column($ps->fetchAll(),'category');$interestTokens=array_values(array_filter(array_map('trim',preg_split('/[,;]+/',(string)($member['interests']??''))?:[]),fn($v)=>text_len($v)>=2));$conditions=[];$bind=[];if($cats){$catMarks=[];foreach($cats as $i=>$cat){$key=':pc'.$i;$catMarks[]=$key;$bind[$key]=$cat;}$conditions[]='category IN ('.implode(',',$catMarks).')';}if(trim((string)($member['home_city']??''))!==''){$conditions[]='(city LIKE :homecity OR location LIKE :homecity)';$bind[':homecity']='%'.trim((string)$member['home_city']).'%';}foreach(array_slice($interestTokens,0,5) as $i=>$interest){$key=':interest'.$i;$conditions[]='(category LIKE '.$key.' OR tags LIKE '.$key.' OR description LIKE '.$key.')';$bind[$key]='%'.$interest.'%';}if($conditions){$sql="SELECT * FROM listings WHERE status='published' AND (".implode(' OR ',$conditions).") AND id NOT IN (SELECT listing_id FROM favorites WHERE user_id=:uid) ORDER BY sponsored DESC,featured DESC,created_at DESC LIMIT 8";$bind[':uid']=current_user_id();$rs=db()->prepare($sql);$rs->execute($bind);$personalized=$rs->fetchAll();}}
$hidden=db()->query("SELECT l.*,COALESCE(v.n,0) view_count FROM listings l LEFT JOIN (SELECT listing_id,COUNT(*) n FROM listing_views GROUP BY listing_id) v ON v.listing_id=l.id WHERE l.status='published' AND l.is_demo=0 AND l.featured=0 AND l.sponsored=0 ORDER BY COALESCE(v.n,0) ASC,l.created_at DESC LIMIT 6")->fetchAll();
$pageTitle='Smart local discovery | '.setting('site_name','MetroGuide');$pageDescription='Search local places naturally, discover hidden gems and find nearby businesses.';include __DIR__.'/includes/header.php';
?>
