<?php if($personalized): ?><section class="lg3-section"><div class="section-heading"><div><span class="eyebrow">BASED ON YOUR SAVED PLACES</span><h2>Picked for your interests</h2><p>Recommendations use your saved categories, selected interests and home city when available.</p></div></div><div class="listing-grid"><?php foreach($personalized as $listing)include __DIR__.'/includes/listing-card.php'; ?></div></section><?php elseif(!current_user()): ?><section class="lg3-callout"><div><strong>Make discovery more personal</strong><p>Sign in and save places you like. Local Guide can use your saved categories to suggest similar listings.</p></div><a class="button button-primary" href="<?= app_path('auth.php?mode=register') ?>">Create a free account</a></section><?php endif; ?>
<section class="lg3-section"><div class="section-heading"><div><span class="eyebrow">LESSER-KNOWN LOCAL FINDS</span><h2>Hidden gems</h2><p>Newer or less-viewed independently listed places. Low traffic is not a quality rating.</p></div></div><div class="listing-grid"><?php foreach($hidden as $listing)include __DIR__.'/includes/listing-card.php'; ?></div></section>
<section class="lg3-section"><div class="section-heading"><div><span class="eyebrow">SMART LOCAL TOOLS</span><h2>Explore more ways</h2></div></div><div class="lg3-feature-grid"><a href="<?= app_path('compare.php') ?>"><i class="fa-solid fa-scale-balanced"></i><strong>Compare places</strong><span>Review details side by side</span></a><a href="<?= app_path('community.php') ?>"><i class="fa-solid fa-people-group"></i><strong>Community hub</strong><span>Guides, photos, Q&A and recommendations</span></a><a href="<?= app_path('marketplace.php') ?>"><i class="fa-solid fa-calendar-check"></i><strong>Book & request quotes</strong><span>Connect with participating businesses</span></a><a href="<?= app_path('messages.php') ?>"><i class="fa-solid fa-comments"></i><strong>Business messages</strong><span>Continue your customer conversations</span></a></div></section>
