<script>
(()=>{const b=document.getElementById('nearbySearch');if(!b)return;b.addEventListener('click',()=>{if(!navigator.geolocation){alert('Location is not available in this browser.');return;}b.disabled=true;b.textContent='Finding your location…';navigator.geolocation.getCurrentPosition(pos=>{const u=new URL(location.href);u.searchParams.set('lat',pos.coords.latitude);u.searchParams.set('lng',pos.coords.longitude);u.searchParams.set('radius',document.getElementById('nearbyRadius').value);location.href=u.toString();},err=>{b.disabled=false;b.innerHTML='<i class="fa-solid fa-location-crosshairs"></i> Find near me';alert(err.code===1?'Location permission was denied. You can still search by neighbourhood.':'Could not get your location. Please try again.');},{enableHighAccuracy:false,timeout:10000,maximumAge:300000});});})();
</script>
